/* GENERATED by the track-record skill on 2026-09-01. Do not edit by hand: run `python -m scripts.cli render-site` instead. */
(() => {
  // Adapted from the Tu Lab site's journey-map component. Two differences that
  // matter: the stops are passed in from the registry rather than hard-coded
  // here, and the shadow root is attached only once d3 and topojson have
  // actually loaded. The second is the important one: attaching it earlier
  // hides the element's own children, so a CDN failure turned the map into a
  // blank box instead of falling back to the plain list written inside it.
  const ATLAS = "https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/countries-110m.json";

  const waitForLibs = () => new Promise((resolve, reject) => {
    const t0 = Date.now();
    const tick = () => {
      if (window.d3 && window.topojson) return resolve();
      if (Date.now() - t0 > 15000) return reject(new Error("d3/topojson did not load"));
      setTimeout(tick, 60);
    };
    tick();
  });

  const readVar = (el, name, fallback) => {
    const v = getComputedStyle(el).getPropertyValue(name).trim();
    return v || fallback;
  };

  class JourneyMap extends HTMLElement {
    connectedCallback() {
      if (this._init) return;
      this._init = true;
      waitForLibs()
        .then(() => fetch(ATLAS).then(r => r.json()))
        .then(topo => {
          this.world = window.topojson.feature(topo, topo.objects.countries);
          this.attachShadow({ mode: "open" });
          this.shadowRoot.innerHTML = this.shell();
          this.svg = this.shadowRoot.querySelector("svg");
          this.draw();
          new ResizeObserver(() => this.draw()).observe(this);
        })
        .catch(e => console.warn("journey-map:", e.message));
    }

    shell() {
      return `<style>
        /* The viewBox is cropped to the route and padded to take in the
           labels, so anything outside it is off-frame by construction.
           overflow:visible (which the original needed, being uncropped) let
           the whole globe spill across the sections below. */
        :host { display:block; width:100%; overflow:hidden; }
        svg { display:block; width:100%; overflow:hidden; }
        .land { fill:var(--jm-land); stroke:var(--jm-edge);
                stroke-width:var(--jm-land-w,0.5px); }
        .grat { fill:none; stroke:var(--jm-grat); stroke-width:var(--jm-land-w,0.5px); }
        .arc { fill:none; stroke:var(--jm-arc); stroke-width:var(--jm-stroke,1.4px);
               stroke-linecap:round;
               transition:stroke-dashoffset 1100ms cubic-bezier(.4,0,.2,1); }
        .leader { stroke:var(--jm-leader); stroke-width:var(--jm-leader-w,0.7px);
                  opacity:0; transition:opacity 500ms ease; }
        .leader.on { opacity:1; }
        .dot { fill:var(--jm-dot); opacity:0; transition:opacity 450ms ease; }
        .dot.on { opacity:1; }
        .halo { fill:none; stroke:var(--jm-dot); stroke-width:1; opacity:0; }
        .halo.on { animation:pulse 2.6s ease-out infinite; }
        @keyframes pulse { 0%{r:var(--jm-r0,4);opacity:.6}
                           100%{r:var(--jm-r1,18);opacity:0} }
        .lbl { font-family:"IBM Plex Mono",ui-monospace,monospace;
               font-size:var(--jm-lbl,10.5px);
               letter-spacing:0.05em; fill:var(--jm-label); opacity:0;
               transition:opacity 500ms ease; }
        .lbl.on { opacity:1; }
        .yr { font-family:"IBM Plex Mono",ui-monospace,monospace;
              font-size:var(--jm-yr,9.5px);
              letter-spacing:0.06em; fill:var(--jm-year); opacity:0;
              transition:opacity 500ms ease; }
        .yr.on { opacity:1; }
        @media (prefers-reduced-motion: reduce) {
          .arc, .dot, .lbl, .yr, .leader { transition:none; }
          .halo.on { animation:none; }
        }
      </style><svg></svg>`;
    }

    stops() {
      try {
        const parsed = JSON.parse(this.getAttribute("stops") || "[]");
        return Array.isArray(parsed) ? parsed : [];
      } catch (e) { return []; }
    }

    static get observedAttributes() { return ["stops", "ratio"]; }
    attributeChangedCallback() { if (this.world) this.draw(); }

    draw() {
      const d3 = window.d3;
      const STOPS = this.stops();
      if (!this.world || !this.svg || STOPS.length < 2) return;
      // The projection is laid out at a fixed internal size and the SVG is
      // then cropped to the route. Every stop on this map is in the northern
      // hemisphere, so drawing the whole globe spent half the height on empty
      // ocean and left the labels too small to separate.
      const W = 2000, H = 1000;
      const proj = d3.geoNaturalEarth1().rotate([-12, 0])
        .fitExtent([[0, 0], [W, H]], { type: "Sphere" });
      const path = d3.geoPath(proj);

      const pts = STOPS.map(s => {
        const p = proj([s.lon, s.lat]);
        return Object.assign({}, s, { x: p[0], y: p[1] });
      });

      // Label offsets are given in CSS pixels and converted into viewBox
      // units, so a label sits the same distance from its pin whatever size
      // the map is drawn at. Keeping them in viewBox units meant the three UK
      // stops, which are only a dozen CSS pixels apart, printed on top of one
      // another as soon as the map got narrower.
      //
      // That makes the frame depend on k and k depend on the frame, so it is
      // solved by iterating: three passes is far more than enough to settle.
      const w = this.clientWidth || 600;
      // Below this the three UK labels cannot be separated whatever the
      // offsets, so the captions are dropped and the map carries city names
      // alone. The years are in the prose beside it either way.
      const withCaptions = w >= 560;
      const textW = s => (s || "").length * 6.2;

      let k = 1, vx = 0, vy = 0, vw = W, vh = H;
      for (let pass = 0; pass < 3; pass++) {
        const xs = [], ys = [];
        pts.forEach(p => {
          const dx = (p.dx || 0) * k, dy = (p.dy || 0) * k;
          // The extent depends on the anchor: an end-anchored label runs its
          // whole width to the left, not half of it, and assuming otherwise
          // clipped the longest caption at the frame edge.
          const wide = Math.max(textW(p.city),
            withCaptions ? textW(p.caption) : 0) * k;
          const a = p.anchor || "middle";
          const left = a === "end" ? wide : (a === "start" ? 0 : wide / 2);
          const right = a === "end" ? 0 : (a === "start" ? wide : wide / 2);
          xs.push(p.x, p.x + dx - left, p.x + dx + right);
          ys.push(p.y, p.y + dy - 12 * k, p.y + dy + (withCaptions ? 20 : 6) * k);
        });
        const bx0 = Math.min.apply(null, xs), bx1 = Math.max.apply(null, xs);
        const by0 = Math.min.apply(null, ys), by1 = Math.max.apply(null, ys);
        const padX = Math.max(20 * k, (bx1 - bx0) * 0.04);
        const padY = Math.max(16 * k, (by1 - by0) * 0.08);
        vx = bx0 - padX; vy = by0 - padY;
        vw = (bx1 - bx0) + padX * 2; vh = (by1 - by0) + padY * 2;
        k = vw / w;
      }
      const h = Math.max(150, Math.min(340, Math.round(w * (vh / vw))));
      const svg = d3.select(this.svg)
        .attr("viewBox", `${vx} ${vy} ${vw} ${vh}`)
        .attr("height", h).attr("role", "img");
      svg.selectAll("*").remove();

      // Strokes and type are given in viewBox units, so they have to be scaled
      // back by however much the crop is being blown up or shrunk to fit. `k`
      // comes from the fitting loop above.
      svg.attr("style",
        `--jm-k:${k}; --jm-stroke:${(1.4 * k).toFixed(2)}px; ` +
        `--jm-lbl:${(10.5 * k).toFixed(2)}px; --jm-yr:${(9.5 * k).toFixed(2)}px; ` +
        `--jm-land-w:${(0.5 * k).toFixed(2)}px; --jm-leader-w:${(0.7 * k).toFixed(2)}px`);

      svg.append("path").attr("class", "grat").attr("d", path({ type: "Sphere" }));
      svg.append("path").attr("class", "grat").attr("d", path(d3.geoGraticule10()));
      svg.append("g").selectAll("path").data(this.world.features).join("path")
        .attr("class", "land").attr("d", path);

      const arcs = pts.slice(1).map((p1, i) => {
        const p0 = pts[i];
        const mx = (p0.x + p1.x) / 2, my = (p0.y + p1.y) / 2;
        const dx = p1.x - p0.x, dy = p1.y - p0.y;
        const len = Math.hypot(dx, dy) || 1;
        const bow = Math.max(14, len * 0.15);
        const cx = mx - (dy / len) * bow, cy = my + (dx / len) * bow;
        return svg.append("path").attr("class", "arc")
          .attr("d", `M${p0.x},${p0.y} Q${cx},${cy} ${p1.x},${p1.y}`);
      });

      this.style.setProperty("--jm-r0", (4 * k).toFixed(1));
      this.style.setProperty("--jm-r1", (18 * k).toFixed(1));
      const nodes = pts.map(p => {
        const g = svg.append("g");
        const dx = (p.dx || 0) * k, dy = (p.dy || 0) * k;
        if (Math.hypot(p.dx || 0, p.dy || 0) > 16) {
          g.append("line").attr("class", "leader")
            .attr("x1", p.x + (dx > 0 ? 3 * k : -3 * k)).attr("y1", p.y)
            .attr("x2", p.x + dx - (dx > 0 ? 4 * k : -4 * k))
            .attr("y2", p.y + dy - 4 * k);
        }
        g.append("circle").attr("class", "halo")
          .attr("cx", p.x).attr("cy", p.y).attr("r", 4 * k);
        g.append("circle").attr("class", "dot").attr("cx", p.x).attr("cy", p.y)
          .attr("r", (p.current ? 4 : 2.8) * k);
        const t = g.append("text").attr("class", "lbl")
          .attr("x", p.x + dx).attr("y", p.y + dy)
          .attr("text-anchor", p.anchor || "middle").text(p.city);
        // A stop whose caption the registry does not record prints the city
        // alone. It is never filled in with a plausible year.
        const y = (p.caption && withCaptions) ? g.append("text").attr("class", "yr")
          .attr("x", p.x + dx).attr("y", p.y + dy + 13 * k)
          .attr("text-anchor", p.anchor || "middle").text(p.caption) : null;
        return { g, p, t, y };
      });

      const reveal = i => {
        const n = nodes[i]; if (!n) return;
        n.g.select(".dot").classed("on", true);
        n.g.select(".leader").classed("on", true);
        n.t.classed("on", true);
        if (n.y) n.y.classed("on", true);
        if (n.p.current) n.g.select(".halo").classed("on", true);
      };

      const still = window.matchMedia
        && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      if (still || this.getAttribute("animate") === "false") {
        nodes.forEach((_, i) => reveal(i));
        return;
      }

      arcs.forEach(a => {
        const L = a.node().getTotalLength();
        a.attr("stroke-dasharray", L).attr("stroke-dashoffset", L);
      });
      reveal(0);
      let t = 320;
      arcs.forEach((a, i) => {
        setTimeout(() => a.attr("stroke-dashoffset", 0), t);
        setTimeout(() => reveal(i + 1), t + 820);
        t += 860;
      });
    }
  }

  if (!customElements.get("journey-map")) customElements.define("journey-map", JourneyMap);
})();
